/* Lot 99: add and accumulate side by side (wf_cssprop_add, wf_cssprop_accumulate) (generated by scripts/lot99_animgen.py; expectations from scripts/lot99_animmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[160];

static int syn(const char *s) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(s, (int)strlen(s), &g_p);
    return g_p.syntax != 0;
}

/* the sum text; the return code is checked against code */
static const char *ad(const char *s, const char *under, const char *v, int code) {
    if (!syn(s)) return "BAD SYNTAX";
    if (wf_cssprop_add(&g_p, under, v, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static const char *ac(const char *s, const char *under, const char *v, int code) {
    if (!syn(s)) return "BAD SYNTAX";
    if (wf_cssprop_accumulate(&g_p, under, v, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static void test_l99_accum_0(void) {
    TEST_ASSERT_EQUAL_STRING("skew(-157deg, 45deg)", ad("'<transform-function>#'", "skew(0deg, 45deg)", "skew(-157deg, 45deg)", 1));
    TEST_ASSERT_EQUAL_STRING("skew(-157deg, 90deg)", ac("'<transform-function>#'", "skew(0deg, 45deg)", "skew(-157deg, 45deg)", 2));
    TEST_ASSERT_EQUAL_STRING("translatex(-20.5%) rotate3d(0, 1, 0, -240.93deg) rotate(-183.4deg) rotate3d(0, 1, 1, 0deg) rotate3d(1, 0, 1, -36deg)", ad("'<transform-function>+'", "translatex(-20.5%) rotate3d(0, 1, 0, -240.93deg)", "rotate(-183.4deg) rotate3d(0, 1, 1, 0deg) rotate3d(1, 0, 1, -36deg)", 2));
    TEST_ASSERT_EQUAL_STRING("rotate(-183.4deg) rotate3d(0, 1, 1, 0deg) rotate3d(1, 0, 1, -36deg)", ac("'<transform-function>+'", "translatex(-20.5%) rotate3d(0, 1, 0, -240.93deg)", "rotate(-183.4deg) rotate3d(0, 1, 1, 0deg) rotate3d(1, 0, 1, -36deg)", 1));
    TEST_ASSERT_EQUAL_STRING("translate(2px)", ad("'*'", "translate(1px)", "translate(2px)", 1));
    TEST_ASSERT_EQUAL_STRING("translate(2px)", ac("'*'", "translate(1px)", "translate(2px)", 1));
    TEST_ASSERT_EQUAL_STRING("rotate3d(0, 0, 1, -283.77deg)", ad("'<transform-function>'", "rotate3d(1, 0, 0, -103.1324deg)", "rotate3d(0, 0, 1, -283.77deg)", 1));
    TEST_ASSERT_EQUAL_STRING("rotate3d(0, 0, 1, -283.77deg)", ac("'<transform-function>'", "rotate3d(1, 0, 0, -103.1324deg)", "rotate3d(0, 0, 1, -283.77deg)", 1));
    TEST_ASSERT_EQUAL_STRING("rgb(205, 216, 255)", ad("'<color>'", "#5e70da", "#aca0e2a5", 2));
    TEST_ASSERT_EQUAL_STRING("rgb(205, 216, 255)", ac("'<color>'", "#5e70da", "#aca0e2a5", 2));
    TEST_ASSERT_EQUAL_STRING("translatex(-135.8px) rotatez(0deg) rotate(0deg) translatex(96px) rotatez(227.88deg) rotate(0deg)", ad("'<length> | <transform-list>'", "translatex(-135.8px) rotatez(0deg) rotate(0deg)", "translatex(96px) rotatez(227.88deg) rotate(0deg)", 2));
    TEST_ASSERT_EQUAL_STRING("translatex(-39.8px) rotatez(227.88deg) rotate(0deg)", ac("'<length> | <transform-list>'", "translatex(-135.8px) rotatez(0deg) rotate(0deg)", "translatex(96px) rotatez(227.88deg) rotate(0deg)", 2));
    TEST_ASSERT_EQUAL_STRING("scale(172%) rotate(0deg) scale(100%) rotate(-360deg)", ad("'<transform-list>'", "scale(172%) rotate(0deg)", "scale(100%) rotate(-360deg)", 2));
    TEST_ASSERT_EQUAL_STRING("scale(1.72) rotate(-360deg)", ac("'<transform-list>'", "scale(172%) rotate(0deg)", "scale(100%) rotate(-360deg)", 2));
    TEST_ASSERT_EQUAL_STRING("371.7281", ad("'<number>'", "370.6281", "1.1", 2));
    TEST_ASSERT_EQUAL_STRING("371.7281", ac("'<number>'", "370.6281", "1.1", 2));
    TEST_ASSERT_EQUAL_STRING("rotate(-210.78deg)", ad("'<transform-function>'", "translatex(0px)", "rotate(-210.78deg)", 1));
    TEST_ASSERT_EQUAL_STRING("rotate(-210.78deg)", ac("'<transform-function>'", "translatex(0px)", "rotate(-210.78deg)", 1));
    TEST_ASSERT_EQUAL_STRING("translate(2px)", ad("'*'", "translate(1px)", "translate(2px)", 1));
    TEST_ASSERT_EQUAL_STRING("translate(2px)", ac("'*'", "translate(1px)", "translate(2px)", 1));
}

